CREATE OR REPLACE FUNCTION public.claim_legacy_producer_job_authoritative_v3_13(p_run uuid, p_job uuid, p_token uuid, p_lease integer)
 RETURNS legacy_producer_claim_v3_11
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_job public.legacy_producer_jobs_v3_11%ROWTYPE;v_run public.legacy_producer_runs_v3_11%ROWTYPE;v_payload public.legacy_producer_job_payloads_v3_11%ROWTYPE;v_prior public.legacy_producer_job_results_v3_11%ROWTYPE;v_source_result public.legacy_producer_job_results_v3_11%ROWTYPE;v_frozen public.legacy_frozen_revision_read_v3_11;v_frozen_json jsonb;v_frozen_bytes bytea;v_frozen_hash text;v_now timestamptz:=date_trunc('second',clock_timestamp());v_hash text;v_selected_hash text;v_source_published_at timestamptz;v_source_collected_at timestamptz;v_read_kind text;v_read_json jsonb;v_read_bytes bytea;v_read_hash text;v_read_count integer;v_include_authority boolean:=false;
BEGIN
  IF p_lease<>120 THEN RETURN NULL; END IF;v_hash:=encode(extensions.digest(convert_to(p_token::text,'utf8'),'sha256'),'hex');
  SELECT * INTO v_run FROM public.legacy_producer_runs_v3_11 WHERE run_id=p_run AND status='running' AND owner_token_hash=v_hash AND lease_expires_at>=v_now FOR UPDATE;
  IF NOT FOUND THEN RETURN NULL; END IF;
  SELECT * INTO v_job FROM public.legacy_producer_jobs_v3_11 WHERE job_id=p_job AND run_id=p_run AND status IN ('queued','retryable') FOR UPDATE;
  IF NOT FOUND THEN RETURN NULL; END IF;
  UPDATE public.legacy_producer_jobs_v3_11 SET status='leased',attempt=attempt+1,owner_token_hash=v_hash,leased_at=v_now,heartbeat_at=v_now,lease_expires_at=v_now+interval '120 seconds' WHERE job_id=p_job RETURNING * INTO v_job;
  UPDATE public.legacy_producer_runs_v3_11 SET heartbeat_at=v_now,lease_expires_at=v_now+interval '120 seconds' WHERE run_id=p_run;
  SELECT * INTO v_payload FROM public.legacy_producer_job_payloads_v3_11 WHERE job_id=p_job;
  IF v_job.predecessor_job_id IS NOT NULL THEN SELECT * INTO v_prior FROM public.legacy_producer_job_results_v3_11 WHERE job_id=v_job.predecessor_job_id; END IF;
  IF v_job.job_kind='revision_shard' THEN
    SELECT selected_revision_row_hash,
      CASE WHEN jsonb_array_length(selected_revision_row_json)=11 THEN (selected_revision_row_json->>5)::timestamptz ELSE NULL END,
      CASE WHEN jsonb_array_length(selected_revision_row_json)=11 THEN (selected_revision_row_json->>6)::timestamptz ELSE (selected_revision_row_json->>5)::timestamptz END
    INTO v_selected_hash,v_source_published_at,v_source_collected_at FROM public.legacy_frozen_source_revisions_v3_11 WHERE run_id=p_run AND revision_id=v_job.revision_id;
    v_frozen:=public.read_legacy_frozen_revision_v3_11(p_run,p_job,v_hash,v_job.revision_id,v_selected_hash);
    IF v_frozen IS NULL THEN RAISE EXCEPTION 'data_integrity_failure';END IF;
    v_frozen_json:=jsonb_build_object('runId',(v_frozen).run_id,'jobId',(v_frozen).job_id,'selectionOrdinal',(v_frozen).selection_ordinal,'sourceKey',(v_frozen).source_key,'revisionId',(v_frozen).revision_id,'sourcePublishedAt',CASE WHEN v_source_published_at IS NULL THEN NULL ELSE to_char(v_source_published_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS"Z"') END,'sourceCollectedAt',to_char(v_source_collected_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS"Z"'),'selectedRevisionRowHash',(v_frozen).selected_revision_row_hash,'rawFieldPayload',(v_frozen).raw_field_payload,'rawCodePointCount',(v_frozen).raw_code_point_count,'rawFieldPayloadAlgorithmVersion',(v_frozen).raw_field_payload_algorithm_version,'ingestionContentRevisionSha256',(v_frozen).ingestion_content_revision_sha256,'canonicalContentAlgorithmVersion',(v_frozen).canonical_content_algorithm_version,'ingestionCanonicalContentHashV3',(v_frozen).ingestion_canonical_content_hash_v3);
    v_frozen_bytes:=convert_to(v_frozen_json::text,'utf8');v_frozen_hash:=encode(extensions.digest(v_frozen_bytes,'sha256'),'hex');
  END IF;
  IF v_job.stage<>'source_sync' THEN
    IF v_job.job_kind='revision_shard' THEN
      v_read_kind:='frozen_revision_authority';
      v_include_authority:=current_setting('stockinsider.legacy_authority_hash',true) IS DISTINCT FROM v_run.authority_hash;
      IF v_include_authority THEN
        SELECT jsonb_build_object(
          'authorityHash',v_run.authority_hash,
          'authorityPages',coalesce(jsonb_agg(jsonb_build_array(page_kind,page_ordinal,page_hash,page_json)
            ORDER BY page_kind,page_ordinal),'[]'::jsonb),
          'frozenRevision',v_frozen_json
        ),coalesce(sum(row_count),0)::integer
        INTO v_read_json,v_read_count
        FROM public.legacy_producer_authority_pages_v3_11 WHERE run_id=p_run;
      ELSE
        v_read_json:=jsonb_build_object('authorityHash',v_run.authority_hash,'authorityPages','[]'::jsonb,
          'frozenRevision',v_frozen_json);
        v_read_count:=1;
      END IF;
    ELSIF v_job.stage='mention_claim_extraction' THEN
      v_read_kind:='mention_shard_results';
      SELECT jsonb_build_object('results',coalesce(jsonb_agg(result.result_json ORDER BY job.shard_ordinal),'[]'::jsonb)),count(*)::integer
      INTO v_read_json,v_read_count
      FROM public.legacy_producer_jobs_v3_11 job JOIN public.legacy_producer_job_results_v3_11 result ON result.job_id=job.job_id
      WHERE job.run_id=p_run AND job.stage='mention_claim_extraction' AND job.job_kind='revision_shard' AND job.status='succeeded';
    ELSIF v_job.stage='candidate_funnel' THEN
      v_read_kind:='candidate_funnel_input';
      v_read_json:=jsonb_build_object(
        'mentionResult',v_prior.result_json,
        'seedSymbols',to_jsonb(v_run.legacy_seed_symbols),
        'priorLedger',coalesce((
          SELECT jsonb_agg(jsonb_build_object(
            'stockId',prior.stock_id,'symbol',prior.symbol,'materialEvidenceHash',prior.material_evidence_hash,
            'disposition',prior.disposition,'sourceCutoff',prior.source_cutoff
          ) ORDER BY prior.stock_id)
          FROM (
            WITH prior_success AS (
              SELECT prior_run.run_id,prior_run.source_cutoff
              FROM public.legacy_producer_runs_v3_11 prior_run
              WHERE prior_run.status='success' AND prior_run.source_cutoff<v_run.source_cutoff
              ORDER BY prior_run.source_cutoff DESC,prior_run.terminal_at DESC,prior_run.run_id LIMIT 1
            )
            SELECT DISTINCT ON (ledger.stock_id) ledger.stock_id,ledger.symbol,ledger.material_evidence_hash,
              ledger.disposition,prior_success.source_cutoff
            FROM prior_success JOIN public.legacy_candidate_discovery_ledger_v3_11 ledger
              ON ledger.source_run_id=prior_success.run_id
            WHERE ledger.stock_id IS NOT NULL
            ORDER BY ledger.stock_id,ledger.recorded_at DESC,ledger.discovery_id
            LIMIT 60
          ) prior
        ),'[]'::jsonb)
      );v_read_count:=coalesce(jsonb_array_length(v_prior.result_json->'candidates'),0);
    ELSIF v_job.stage='facts_refresh' THEN
      v_read_kind:='candidate_fact_plane';
      v_read_json:=public.read_legacy_candidate_fact_plane_v3_11(v_run.source_cutoff,v_prior.result_json);
      v_read_count:=coalesce(jsonb_array_length(v_prior.result_json->'candidates'),0);
    ELSIF v_job.stage='analysis_revision' THEN
      v_read_kind:='analysis_revision_input';
      v_read_json:=jsonb_build_object(
        'factsResult',v_prior.result_json,
        'sourceCutoff',to_char(v_run.source_cutoff AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS"Z"'),
        'producerCommitSha',v_run.producer_commit_sha,
        'priorRevisions',coalesce((
          SELECT jsonb_agg(jsonb_build_object(
            'symbol',prior.symbol,'revisionId',prior.revision_id,'materialChangeHash',prior.material_change_hash,
            'analysisGeneratedAt',to_char(prior.analysis_generated_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS"Z"')
          ) ORDER BY prior.symbol)
          FROM (
            SELECT DISTINCT ON (revision.symbol) revision.symbol,revision.revision_id,
              revision.material_change_hash,revision.analysis_generated_at,revision.source_cutoff
            FROM public.legacy_analysis_revisions_v3_11 revision
            WHERE revision.symbol IN (
              SELECT decision.value->>'symbol' FROM jsonb_array_elements(coalesce(v_prior.result_json->'decisions','[]'::jsonb)) decision(value)
            ) AND revision.source_cutoff<v_run.source_cutoff
            ORDER BY revision.symbol,revision.source_cutoff DESC,revision.recorded_at DESC,revision.revision_id
          ) prior
        ),'[]'::jsonb)
      );v_read_count:=coalesce(jsonb_array_length(v_prior.result_json->'decisions'),0);
    ELSE
      SELECT result.* INTO STRICT v_source_result
      FROM public.legacy_producer_jobs_v3_11 source_job
      JOIN public.legacy_producer_job_results_v3_11 result ON result.job_id=source_job.job_id
      WHERE source_job.run_id=p_run AND source_job.stage='source_sync'
        AND source_job.job_kind='stage_barrier' AND source_job.status='succeeded';
      IF jsonb_typeof(v_source_result.result_json->'legacyPayloads')<>'object'
        OR jsonb_typeof(v_source_result.result_json->'legacyPayloadHashes')<>'object'
      THEN RAISE EXCEPTION 'data_integrity_failure';END IF;
      v_read_kind:='compact_projection_input';v_read_json:=jsonb_build_object('analysisResult',v_prior.result_json,'sourceCutoff',to_char(v_run.source_cutoff AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS"Z"'),'producerCommitSha',v_run.producer_commit_sha,'workerSha256',v_run.worker_sha256,'legacyPayloads',v_source_result.result_json->'legacyPayloads','legacyPayloadHashes',v_source_result.result_json->'legacyPayloadHashes',
        'legacySourceResultHash',v_source_result.result_hash,
        'legacyRadarCompatibility',v_source_result.result_json->'legacyRadarCompatibility');v_read_count:=coalesce(jsonb_array_length(v_prior.result_json->'decisions'),0);
    END IF;
    v_read_bytes:=convert_to(v_read_json::text,'utf8');v_read_hash:=encode(extensions.digest(v_read_bytes,'sha256'),'hex');
    IF octet_length(v_read_bytes)>3145728 OR v_read_count>20000 THEN RAISE EXCEPTION 'bound_violation';END IF;
  END IF;
  RETURN ROW(v_job.run_id,v_job.job_id,v_job.stage,v_job.job_kind,v_job.stage_ordinal,v_job.shard_ordinal,v_job.execution_ordinal,v_job.revision_id,v_job.attempt,
    v_payload.payload_canonical,v_payload.payload_json,v_payload.payload_hash,v_prior.result_canonical,v_prior.result_json,v_prior.result_hash,
    CASE WHEN v_job.stage='source_sync' THEN 'legacy-discovery-authority-v1' ELSE NULL END,CASE WHEN v_job.stage='source_sync' THEN v_run.authority_canonical ELSE NULL END,
    CASE WHEN v_job.stage='source_sync' THEN v_run.authority_json ELSE NULL END,CASE WHEN v_job.stage='source_sync' THEN v_run.authority_hash ELSE NULL END,v_frozen_bytes,v_frozen_json,v_frozen_hash,
    v_read_kind,v_read_bytes,v_read_json,v_read_hash,v_read_count,v_job.lease_expires_at)::public.legacy_producer_claim_v3_11;
END $function$

