CREATE OR REPLACE FUNCTION public.claim_legacy_producer_job_authoritative_v3_15(p_run uuid, p_job uuid, p_token uuid, p_lease integer)
 RETURNS legacy_producer_claim_v3_11
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_claim public.legacy_producer_claim_v3_11;v_prior jsonb;v_conflict boolean;v_cutoff timestamptz;
BEGIN
  v_claim:=public.claim_legacy_producer_job_authoritative_v3_13(p_run,p_job,p_token,p_lease);
